test("env vars override file values for nested keys", () => {
  const cfg = loadConfig({ env: { APP_CACHE__TTL_SECONDS: "60" }, file: { cache: { ttlSeconds: 600 } } });
  assert.equal(cfg.cache.ttlSeconds, 60);
