test("production: APP_CACHE__TTL_SECONDS overrides the file", () => {
  const cfg = loadConfig({
    env: { APP_ENV: "production", APP_CACHE__TTL_SECONDS: "30", APP_CACHE__REDIS__MAX_RETRIES: "5" },
    file: { cache: { ttlSeconds: 600, redis: { host: "redis.internal", maxRetries: 2 } } },
  });
  assert.equal(cfg.cache.ttlSeconds, 30);
  assert.equal(cfg.cache.redis.maxRetries, 5);
  assert.equal(cfg.cache.redis.host, "redis.internal");
});

